def pickLocale(loc: Any = js.UNDEF) -> Any:
    return loc if (js.truthy(loc) and js.truthy(own(LABELS, loc))) else "en"


def verdictLabel(loc: Any, verdict: Any) -> Any:
    v: Any = js.nullish(verdict, "")
    table: Any = js.nullish(
        (
            _v1
            if js.defined(_v1 := js.get(VERDICT_LABELS, pickLocale(loc)))
            else js.get(VERDICT_LABELS, "en")
        ),
        {},
    )
    return js.nullish(own(table, v), v)


def verdictDescription(loc: Any, verdict: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_MATCH, l)
    if js.truthy(south):
        if ((verdict == "excellent") or (verdict == "good")) or (verdict == "fair"):
            return js.get(js.get(south, "verdict"), verdict)
        return js.get(js.get(south, "verdict"), "poor")
    _case2: Any = verdict
    if _case2 == "excellent":
        if l == "hi":
            return "उत्तम मिलान — सभी क्षेत्रों में सामंजस्य की संभावना अधिक है।"
        if l == "mr":
            return "उत्तम जुळवणी — सर्व क्षेत्रांत सामंजस्याची शक्यता अधिक आहे."
        return "Excellent match — high compatibility across all areas."
    elif _case2 == "good":
        if l == "hi":
            return "अच्छा मिलान — विवाह के लिए अनुकूल योग।"
        if l == "mr":
            return "चांगली जुळवणी — विवाहासाठी अनुकूल योग."
        return "Good match — favorable indications for marriage."
    elif _case2 == "fair":
        if l == "hi":
            return "सामान्य मिलान — कुछ कूटों में कमी, परंतु आगे बढ़ने योग्य।"
        if l == "mr":
            return "सामान्य जुळवणी — काही कूटांमध्ये कमतरता, परंतु पुढे जाण्यायोग्य."
        return "Fair match — some kootas underscore but workable with awareness."
    else:
        if l == "hi":
            return "अल्प मिलान — कई कूटों में कमी, सावधानीपूर्वक विचार आवश्यक।"
        if l == "mr":
            return "अल्प जुळवणी — अनेक कूटांमध्ये कमतरता, काळजीपूर्वक विचार आवश्यक."
        return "Low score — multiple kootas underscore; careful consideration advised."


def doshaClass(d: Any) -> Any:
    if not js.truthy(js.get(d, "Computed")):
        return "not-computed"
    if js.truthy(js.get(d, "HasDosha")) and js.truthy(js.get(d, "Cancelled")):
        return "cancelled"
    if js.truthy(js.get(d, "HasDosha")):
        return "has-dosha"
    return "no-dosha"


def joinStrings(items: Any, sep: Any) -> Any:
    return js.join(items, sep) if js.is_array(items) else ""


def doshaSummary(loc: Any, d: Any) -> Any:
    l: Any = pickLocale(loc)
    south: Any = js.get(SOUTH_MATCH, l)
    if js.truthy(south):
        if not js.truthy(js.get(d, "Computed")):
            return js.get(south, "mangalNotComputed")
        if not js.truthy(js.get(d, "HasDosha")):
            return js.get(south, "mangalNone")
        type_: Any = (
            js.get(south, "typePurn")
            if (js.get(d, "Type") == "purn")
            else (
                js.get(south, "typeMild")
                if (js.get(d, "Type") == "mild")
                else js.nullish(js.get(d, "Type"), "")
            )
        )
        hs: Any = listOf(js.get(d, "HousesOccupied"))
        lag: Any = js.map_(js.filter_(hs, (lambda h: js.gt(h, 0))), js.s)
        moon: Any = js.map_(js.filter_(hs, (lambda h: js.lt(h, 0))), (lambda h: js.s(js.neg(h))))
        parts: Any = []
        if js.truthy(js.length(lag)):
            parts.append(js.get(south, "fromLagna")(js.join(lag, ", ")))
        if js.truthy(js.length(moon)):
            parts.append(js.get(south, "fromMoon")(js.join(moon, ", ")))
        out: Any = js.get(south, "mangal")(type_, js.join(parts, "; "))
        if js.truthy(js.get(d, "Cancelled")):
            out = js.add(
                out,
                js.add(js.get(south, "cancelled"), joinStrings(js.get(d, "CancelReasons"), ", ")),
            )
        return out
    if not js.truthy(js.get(d, "Computed")):
        if l == "hi":
            return "मंगल दोष की जाँच नहीं हुई — जन्म स्थान (अक्षांश/देशांतर) नहीं दिया गया।"
        if l == "mr":
            return "मंगळ दोष तपासला नाही — जन्मस्थान (अक्षांश/रेखांश) दिलेले नाही."
        return "Mangal Dosha not evaluated — birth latitude/longitude not provided."
    if not js.truthy(js.get(d, "HasDosha")):
        if l == "hi":
            return "मंगल दोष नहीं है।"
        if l == "mr":
            return "मंगळ दोष नाही."
        return "No Mangal Dosha present."
    typeLabel: Any = (
        (
            "पूर्ण"
            if (js.get(d, "Type") == "purn")
            else ("अल्प" if (js.get(d, "Type") == "mild") else js.nullish(js.get(d, "Type"), ""))
        )
        if ((l == "hi") or (l == "mr"))
        else (
            "full"
            if (js.get(d, "Type") == "purn")
            else ("mild" if (js.get(d, "Type") == "mild") else js.nullish(js.get(d, "Type"), ""))
        )
    )
    hs_2: Any = listOf(js.get(d, "HousesOccupied"))
    lagnaH: Any = js.map_(js.filter_(hs_2, (lambda h: js.gt(h, 0))), js.s)
    moonH: Any = js.map_(js.filter_(hs_2, (lambda h: js.lt(h, 0))), (lambda h: js.s(js.neg(h))))
    houseParts: Any = []
    if l == "hi":
        if js.truthy(js.length(lagnaH)):
            houseParts.append(("लग्न से " + js.join(lagnaH, ", ")))
        if js.truthy(js.length(moonH)):
            houseParts.append(("चंद्र से " + js.join(moonH, ", ")))
    elif l == "mr":
        if js.truthy(js.length(lagnaH)):
            houseParts.append(("लग्नापासून " + js.join(lagnaH, ", ")))
        if js.truthy(js.length(moonH)):
            houseParts.append(("चंद्रापासून " + js.join(moonH, ", ")))
    else:
        if js.truthy(js.length(lagnaH)):
            houseParts.append((js.join(lagnaH, ", ") + " from lagna"))
        if js.truthy(js.length(moonH)):
            houseParts.append((js.join(moonH, ", ") + " from Moon"))
    houses: Any = js.join(houseParts, "; ")
    out_2: Any = js.UNDEF
    if l == "hi":
        out_2 = "मंगल दोष (" + js.s(typeLabel) + ") — भाव: " + js.s(houses) + "।"
    elif l == "mr":
        out_2 = "मंगळ दोष (" + js.s(typeLabel) + ") — स्थाने: " + js.s(houses) + "."
    else:
        out_2 = "Mangal Dosha (" + js.s(typeLabel) + ") — house(s): " + js.s(houses) + "."
    if js.truthy(js.get(d, "Cancelled")):
        reasons: Any = joinStrings(js.get(d, "CancelReasons"), ", ")
        if l == "hi":
            out_2 = js.add(out_2, (" रद्द: " + js.s(reasons)))
        elif l == "mr":
            out_2 = js.add(out_2, (" रद्द: " + js.s(reasons)))
        else:
            out_2 = js.add(out_2, (" Cancelled: " + js.s(reasons)))
    return out_2


def nadiClass(n: Any) -> Any:
    _case3: Any = js.get(n, "Severity")
    if _case3 == "exempted":
        return "cancelled"
    elif _case3 == "high":
        return "has-dosha"
    else:
        return "no-dosha"


def nadiSummary(loc: Any, n: Any) -> Any:
    l: Any = pickLocale(loc)
    boy: Any = js.nullish(js.get(n, "BoyNadi"), "")
    girl: Any = js.nullish(js.get(n, "GirlNadi"), "")
    south: Any = js.get(SOUTH_MATCH, l)
    if js.truthy(south):
        if js.get(n, "Severity") == "none":
            return js.get(south, "nadiNone")(boy, girl)
        if js.get(n, "Severity") == "exempted":
            return js.get(south, "nadiExempted")(joinStrings(js.get(n, "Exceptions"), ", "))
        return js.get(south, "nadiHigh")(boy)
    _case4: Any = js.get(n, "Severity")
    if _case4 == "none":
        if l == "hi":
            return "नाड़ी दोष नहीं है। (वर: " + js.s(boy) + ", वधू: " + js.s(girl) + ")"
        if l == "mr":
            return "नाडी दोष नाही. (वर: " + js.s(boy) + ", वधू: " + js.s(girl) + ")"
        return "No Nadi Dosha. (Boy: " + js.s(boy) + ", Girl: " + js.s(girl) + ")"
    elif _case4 == "exempted":
        exc: Any = joinStrings(js.get(n, "Exceptions"), ", ")
        if l == "hi":
            return "नाड़ी दोष है परन्तु शास्त्रीय अपवाद से रद्द (" + js.s(exc) + ")"
        if l == "mr":
            return "नाडी दोष आहे परंतु शास्त्रीय अपवादाने रद्द (" + js.s(exc) + ")"
        return "Nadi Dosha present but exempted by classical rule (" + js.s(exc) + ")"
    else:
        if l == "hi":
            return "नाड़ी दोष — दोनों की नाड़ी समान (" + js.s(boy) + ")। शास्त्रीय रूप से प्रतिकूल।"
        if l == "mr":
            return "नाडी दोष — दोघांची नाडी समान (" + js.s(boy) + "). शास्त्रानुसार प्रतिकूल."
        return "Nadi Dosha — both share " + js.s(boy) + " nadi. Classically unfavorable."


def matchVerdict(data: Any) -> Any:
    if js.truthy(js.get(data, "FinalVerdict")):
        return js.get(data, "FinalVerdict")
    total: Any = js.nullish(js.get_optional(js.get(data, "Ashtakoota"), "Total"), 0)
    if js.ge(total, 24):
        return "Marriage indications are favorable. Study both charts for the timing."
    return "Score is below conventional threshold (24/36). Consider remedies and a detailed study of both charts."


def formatGenerated(iso: Any = js.UNDEF) -> Any:
    if not js.truthy(iso):
        return ""
    d: Any = parseTimestamp(iso)
    if js.is_nan(d.get_time()):
        return iso

    def p(n: Any) -> Any:
        return js.pad_start(js.s(n), 2, "0")

    return (
        js.s(d.utc_year())
        + "-"
        + js.s(p(js.add(d.utc_month(), 1)))
        + "-"
        + js.s(p(d.utc_date()))
        + " "
        + js.s(p(d.utc_hours()))
        + ":"
        + js.s(p(d.utc_minutes()))
        + " UTC"
    )


