def renderMatchMakingHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "Locale": safeLocale(js.get(data, "Locale"))})
    resolved: Any = resolveBranding(js.get(data, "Branding"), branding)
    t: Any = makeLabeler(LABELS, js.get(data, "Locale"))
    boy: Any = js.nullish(js.get(data, "Boy"), {})
    girl: Any = js.nullish(js.get(data, "Girl"), {})
    ashtakoota: Any = js.nullish(js.get(data, "Ashtakoota"), {})
    kootas: Any = js.get(ashtakoota, "Kootas") if js.is_array(js.get(ashtakoota, "Kootas")) else []
    verdict: Any = js.nullish(js.get(ashtakoota, "Verdict"), "")
    boyName: Any = js.nullish(js.get(boy, "name"), "")
    girlName: Any = js.nullish(js.get(girl, "name"), "")

    def subjectMeta(s: Any) -> Any:
        return (
            esc(t("born"))
            + " "
            + esc(js.get(s, "birth_date"))
            + "<br>"
            + esc(js.get(s, "birth_time"))
            + "<br>"
            + esc(js.get(s, "birth_place"))
            + "<br>"
            + esc(t("nakshatra"))
            + ": "
            + esc(js.get(s, "nakshatra"))
        )

    cover: Any = (
        ('<section class="cover">\n  ')
        + js.s(coverBrandingHtml(resolved))
        + ("\n  <h1>")
        + esc(t("title_match"))
        + ('</h1>\n  <div class="subjects">\n    <div class="subject-col">\n      <h2>')
        + esc(boyName)
        + ('</h2>\n      <div class="meta">')
        + js.s(subjectMeta(boy))
        + (
            "</div>\n"
            "    </div>\n"
            '    <div class="vs">⚭</div>\n'
            '    <div class="subject-col">\n'
            "      <h2>"
        )
        + esc(girlName)
        + ('</h2>\n      <div class="meta">')
        + js.s(subjectMeta(girl))
        + ('</div>\n    </div>\n  </div>\n  <div class="generated">')
        + esc(t("generated"))
        + " "
        + esc(formatGenerated(js.get(data, "GeneratedAt")))
        + ("</div>\n</section>")
    )
    kootaRows: Any = js.join(
        js.map_(
            kootas,
            (
                lambda k: (
                    "<tr><td>"
                    + esc(js.get(k, "name"))
                    + '</td><td class="score">'
                    + esc(js.get(k, "Max"))
                    + '</td><td class="score">'
                    + esc(js.get(k, "score"))
                    + "</td><td>"
                    + esc(js.get(k, "Reason"))
                    + "</td></tr>"
                )
            ),
        ),
        "",
    )
    totalRow: Any = (
        '<tr class="total"><td>'
        + esc(t("total"))
        + '</td><td class="score">'
        + esc(js.get(ashtakoota, "Max"))
        + '</td><td class="score">'
        + esc(js.get(ashtakoota, "Total"))
        + "</td><td>"
        + esc(verdictLabel(js.get(data, "Locale"), verdict))
        + "</td></tr>"
    )
    ashtakootaTable: Any = (
        "<h2>"
        + esc(t("section_ashtakoota"))
        + ("</h2>\n<table>\n  <thead>\n    <tr>\n      <th>")
        + esc(t("koota"))
        + ('</th>\n      <th class="score">')
        + esc(t("max"))
        + ('</th>\n      <th class="score">')
        + esc(t("score"))
        + ("</th>\n      <th>")
        + esc(t("details"))
        + ("</th>\n    </tr>\n  </thead>\n  <tbody>")
        + js.s(kootaRows)
        + js.s(totalRow)
        + ('</tbody>\n</table>\n<div class="verdict ')
        + esc(verdict)
        + ('">\n  <h3>')
        + esc(t("ashtakoota_verdict"))
        + ": "
        + esc(verdictLabel(js.get(data, "Locale"), verdict))
        + ("</h3>\n  <p>")
        + esc(verdictDescription(js.get(data, "Locale"), verdict))
        + ("</p>\n</div>")
    )
    mangalBoy: Any = js.nullish(js.get(data, "MangalDoshaBoy"), {})
    mangalGirl: Any = js.nullish(js.get(data, "MangalDoshaGirl"), {})
    nadi: Any = js.nullish(js.get(data, "NadiDosha"), {})
    doshas: Any = (
        "<h2>"
        + esc(t("section_doshas"))
        + ("</h2>\n<h3>")
        + esc(t("mangal_dosha"))
        + " — "
        + esc(boyName)
        + ('</h3>\n<div class="dosha-block ')
        + esc(doshaClass(mangalBoy))
        + '">'
        + esc(doshaSummary(js.get(data, "Locale"), mangalBoy))
        + ("</div>\n<h3>")
        + esc(t("mangal_dosha"))
        + " — "
        + esc(girlName)
        + ('</h3>\n<div class="dosha-block ')
        + esc(doshaClass(mangalGirl))
        + '">'
        + esc(doshaSummary(js.get(data, "Locale"), mangalGirl))
        + ("</div>\n<h3>")
        + esc(t("nadi_dosha"))
        + ('</h3>\n<div class="dosha-block ')
        + esc(nadiClass(nadi))
        + '">'
        + esc(nadiSummary(js.get(data, "Locale"), nadi))
        + "</div>"
    )
    finalVerdict: Any = (
        "<h2>"
        + esc(t("section_final"))
        + ('</h2>\n<div class="verdict ')
        + esc(verdict)
        + ('">\n  <p>')
        + esc(matchVerdict(data))
        + ("</p>\n</div>")
    )
    bodyHtml: Any = js.join([cover, ashtakootaTable, doshas, finalVerdict], ("\n\n"))
    return layoutDocument(
        {
            "lang": js.get(data, "Locale"),
            "title": (js.s(t("title_match")) + " — " + js.s(boyName) + " × " + js.s(girlName)),
            "branding": resolved,
            "bodyHtml": bodyHtml,
            "extraCss": EXTRA_CSS,
        }
    )
